def is_prime(n: int) -> bool:
    """Return True if n is a prime number, else False. Runs in O(sqrt(n)) time."""
    if n <= 1:
        return False
    if n <= 3:
        return True  # 2 and 3 are prime
    if n % 2 == 0 or n % 3 == 0:
        return False

    i = 5
    # Check divisibility by numbers of the form 6k ± 1 up to sqrt(n)
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True
```

